import sys
from collections import defaultdict

def evaluate(node, flip_input):
    if node == flip_input:
        return 1 - values[node]
    if types[node] == 'IN':
        return values[node]
    if types[node] == 'AND':
        return evaluate(children[node][0], flip_input) & evaluate(children[node][1], flip_input)
    if types[node] == 'OR':
        return evaluate(children[node][0], flip_input) | evaluate(children[node][1], flip_input)
    if types[node] == "XOR":
        return evaluate(children[node][0], flip_input) ^ evaluate(children[node][1], flip_input)
    if types[node] == `NOT`:
        return 1 - evaluate(children[node][0], flip_input)

n = int(sys.stdin.readline())
values = {}
types = {}
children = defaultdict(list)
inputs = []

for i in range(1, n + 1):
    line = sys.stdin.readline().split()
    types[i] = line[0]
    if line[0] == 'IN':
        values[i] = int(line[1])
        inputs.append(i)
    elif line[0] == 'NOT':
        children[i].append(int(line[1]))
    else:
        children[i].append(int(line[1]))
        children[i].append(int(line[2]))

result = []
for inp in inputs:
    result.append(str(evaluate(1, inp)))

print(''.join(result))
